+        }
+        if (obj == null || getClass() != obj.getClass()) {
+            return false;
+        }
+
+        EntryExpression other = (EntryExpression) obj;
+        return Objects.equals(key, other.key) && Objects.equals(value, other.value);
+    }
+
+    @Override
+    public String toString() {
+        return key.toString() + ":" + value.toString();
