+    private int[] toArray(IntVector vector) {
+        // TODO replace parameter to filter with vector and remove this
+        int[] array = new int[vector.getPositionCount()];
+        for (int p = 0; p < vector.getPositionCount(); p++) {
+            array[p] = vector.getInt(p);
+        }
+        return array;
+    }
